add("MP-017","方向：女性出任。下届香港特首将由女性出任，即女性候选人最终胜出，男性候选人陪跑。应期：2017年3月26日选举委员会投票当日揭晓。置信中高。","tradition：modern-masters/相法时事预测（卡面无tradition字段，依据provenance为香港商报引明报、问性别之占自决）\nsystems_used：时事相法/生肖年命互参；卡面事实：梁振英不连任、林郑月娥改口重新考虑参选、曾俊华已辞职备选——女性参选人中唯林郑具建制支持与现职优势，男性阵营分散，故断女胜。无盘面残损。",0.68)
add("MP-018","方向：不能当选（negative）。曾俊华虽民望为候选人中最高，但民望不等于选委会票源，最终败于获北京支持的对手，止于陪跑。应期：2017年3月26日投票日落败揭晓。","tradition：相法（卡面无tradition字段，依据《睇相王》睇相栏目自决）\nsystems_used：面相/气色相法＋选情事实核对；事实优先序：卡面明言传媒普遍指对手获北京支持、选情占优，选委会小圈子选举票源结构压过公众民望，相法所见贵气不足以登顶，故断不当选。",0.72)
add("MP-019","方向：林郑月娥当选。2017年香港行政长官选举花落林郑月娥（女性、1957酉年生者），曾俊华次之、胡国兴得票最低，三人排序为林郑＞曾＞胡。应期：2017年3月26日投票当日。","tradition：相法/命理（卡面无tradition字段，依据《新玄机》风水命理杂志及三人生年自决）\nsystems_used：生肖年命＋相法时事互参；林郑与胡同为酉年，酉年人在丁酉选举年得岁君扶助，而林郑兼具现职与建制票源，胡为退休法官票源最弱；曾卯年与酉年相冲，声势受压。故取林郑胜、曾次、胡末。",0.7)
# OC bazi
def bazi(cid,pred,basis,conf=0.6):
    add(cid,pred,"tradition：bazi（卡面无tradition字段，依据卡面四柱自决）\nsystems_used：八字子平（调候、格局、旺衰、大运流年）；"+basis,conf)
bazi("OC-001","方向：先盛后衰。戊土日主生辰月得令、财星壬子透时、甲木七杀坐戌，军政贵显至主政一方/军阀首领级，为一生高峰在中年；晚年运走衰地、杀财交煎，权势尽失、下野落魄，晚景孤寒，客死异乡之象。等级：上层军政而非帝王，晚年降格有据——日主晚运无根、财杀无制。","四柱甲戌戊辰戊申壬子：戊土旺相、申子辰水势助财，财旺生杀，前段成势；后段土金水耗、木杀攻身无印化，故先盛后衰。卡面已言曾主政一方后下野，与盘面同向。")
bazi("OC-002","方向：大贵大富。庚金日主坐申禄、亥卯财旺、甲乙财星并透、己印贴身，财印相辅，主掌财政金融至部会首长/院级边缘高位，富甲一方；一生行运多顺、晚年安享高寿而终。险年仅在火旺克金之运年有职务起伏，不伤根本。","四柱甲午乙亥庚申己卯：庚得禄于申、财源茂盛、印星护身，格局清纯足级，故按足级断富贵双全，不降格。")
bazi("OC-003","方向：富贵名高、晚年退守。庚金生午月官杀火旺、卯木财星两见、己印化杀，商界领袖级巨富、名位显于沪上；中年火金交战有经营起伏与身体火炎之疾，晚年印运得安、急流勇退可保富终老。","四柱丁卯丙午庚午己卯：官杀旺而印透，杀印相生转贵于商；财多耗金，故富大于官、晚年宜退。")
bazi("OC-004","方向：清贵仕途、外交名臣。乙木日主生卯月得禄、癸印子水滋身、丙伤泄秀，文名与外交才具出众，仕至公使/内阁级；格局清而不厚于财，一生平稳少大难，晚年以清望退居、安稳终老。","四柱丁丑癸卯乙巳丙子：乙木根深、印星两见护身、食伤吐秀，贵在文外交而非权柄，故等级定为清贵高位。")
bazi("OC-005","方向：贵显于法学司法。乙木日主卯未木局成势、丁食透月、己财两见，学问与词章出众，仕至法院院长级/司法高位，并有国际法学声名；中年后名大于权，晚年著作声望长存，安稳而终。","四柱己亥丁卯乙未己卯：木势成局、食神生财、根基深厚，无冲破主字，故足级断司法贵显。")
bazi("OC-006","方向：先挫后复、终保基业。当前1935乙亥年之挫为流年冲动，非格局崩坏；戊土日主申月、午印寅杀，实业根基深厚，企业危机在随后数年内逐步化解、重整复兴，命主仍以纺织面粉巨头之位终老，晚年虽有战乱迁徙之扰，基业不至倾覆。应期尺度：年档，先定年——1936-1938间见转机。","四柱癸酉庚申戊午甲寅：戊土得午印寅杀生扶、申酉金泄而生财，根深；乙亥年亥冲动致一时受挫，属运年引动而非格局破，故断可复。问近段走势，远段以年档收束。",0.62)
bazi("OC-007","方向：才高命薄、早逝。甲木日主申月七杀两见、寅申冲、甲木三透争合无印化杀，性情狂放不羁、文才惊世而仕途无成，依父荫享富贵闲名；杀重身危、无救应，寿数短促，约四十岁前后（1931辛未年前后）以疾/酒色耗身而终，不得高寿。","四柱庚寅甲申甲申甲戌：三甲并透比劫争、双申杀冲寅根，根被拔、杀无制，等级与寿数降格依据即在此——根冲杀重，故断早逝。卡面问逝后验推，与盘面短寿同向。")
bazi("OC-008","方向：军政高位、权位可观而难至极峰。乙木日主酉月、未卯根聚、己财透时，仕至省主席级/军政一方之任，中年运佳时权柄最重；金旺克木，晚运金水之地有退职与起伏，终能以资望退居、保位终老。","四柱戊子辛酉乙未己卯：乙木有卯未之根可任财官，酉金官杀有度，格局中上足级至省部级，不拔高至中枢极峰。异说丙子时原书已斥误，不取。")
add("OC-009","方向：外交贵显、富贵寿考。命主以顶尖外交官终身致位，历使节与内阁、国际声望极高，晚年仍居国际司法/外交荣衔，婚姻与财富皆平稳丰厚，高寿而终。置信低：四柱缺载，不以臆补排盘。","tradition：bazi（卡面无tradition字段，依据命书应运篇论造体例自决）\nsystems_used：八字子平（仅据卡面事实作有限判断）；输入残损：卡面四柱仅写「原书应运篇下论造、四柱以原书为准、转录本个别字待校」，无实际干支可排，故不臆补四柱与大运，仅据已历任使节内阁之事实定贵显等级并降置信。",0.35)
bazi("OC-010","方向：帝位已失、余生颠沛而寿不短。壬水日主寅月、午火财星三重、丙庚并透，生于帝室而格局财多身弱、食伤泄气，退位后无复辟成功之命：中年有被外力扶立作傀儡君主一段（名位虚悬、实权在人），晚年再逢牢狱/管束之厄后获释，以平民终老，寿至六十上下。","四柱丙午庚寅壬午丙午：三午财火围壬、寅午助财，身弱财重，主富贵有名无实、受人摆布；无大运表（卡面注明），应期只定年档不定细运。")
bazi("OC-011","方向：名盛而命薄、非命横夭。己土日主巳月、亥水两见冲巳、乙杀透时、辛食吐秀，演艺才华与艳名极盛，感情纠葛与舆论压力为一生主厄；巳亥冲动、杀无制而身心受逼，寿数短促，约二十余岁盛年时以自尽/横夭方式骤然离世，不得善终。险年即逝世之年（乙亥、火水交冲之年）。","四柱庚戌辛巳己亥乙亥：双亥冲巳火印根，印根一拔则无所依，乙杀攻身，降格与短寿依据在此。卡面问逝后验推，与盘面横夭同向。")
bazi("OC-012","方向：少年成名、中年婚姻与名声多波折、晚年趋平。丁火日主辰月、未土两见、戊伤并透、申金财星，泳坛冠军级早成名；伤官旺而官星不显，婚姻宫未土重叠主感情多变、婚事不止一段之象或夫妻聚少离多，中年名利渐退，晚年以平淡安居终老，寿数不短。行运：五岁起运己巳庚午火土助伤生财为成名段，辛未壬申后转金水渐平。","四柱己未戊辰丁未戊申＋卡面大运：早运火土旺助成名，伤官重压夫星，故婚姻降格依据为伤官两透、官星藏而不显。")
bazi("OC-013","方向：艺业登峰、晚年逢厄。辛金日主丑月、酉金禄旺、甲财午丁并见，京剧宗师级盛名、中年富贵双全；八岁起运后半生运入火乡本可显达，然晚年逢社会剧变之运年（火杀攻金、财被劫），有抄家/迫害式困厄与疾苦，晚景凄凉，约八十岁前后离世。","四柱甲午丁丑辛酉甲午：金旺成势、财官俱显足级宗师；晚年降格依据为双午丁火杀星待运引爆、酉金在乱世运中受克。")
bazi("OC-014","方向：仕途中等偏上、起伏多而终有退路。壬水日主卯月、寅木食伤成势、庚辛印透年时、丑辰湿土为官，仕至财政厅长级为顶，不再上中枢；食伤旺主与上司/体制摩擦，行运金水年得志、火土年有罢黜财务纠纷，晚年以闲退终老。","四柱庚辰己卯壬寅辛丑：食伤泄秀、印星护身，贵而多动荡，等级止于省级财职，依据为官星己土弱而坐卯受克。")
bazi("OC-015","方向：君主贵命、一生平稳尊荣。甲木日主巳月、辰土财、子印甲比扶身，身财两停、印星护体，王位稳固、在位长久，历一次大战而王室不倾；晚年安享尊荣、高寿在位而终（寿约七十）。","四柱乙丑辛巳甲辰甲子：甲木得子印丑辰之根、辛官有度，格局端正无冲破，故足级断长在位与高寿。卡面言据西报生庚演造，生庚若误则断随误，已注此限。")
bazi("OC-016","方向：以命学立身、清贵而非富贵。庚金日主卯月、子水伤官、辰亥根库、辛庚比劫并透，聪明绝顶、文章口才成名，职业即以命理/著述立身，一生衣食丰厚、名满南北而官位无缘；晚年著述声望不衰，安稳终老，寿数中上。","四柱辛亥辛卯庚子庚辰：伤官佩印式清贵、比劫旺主同行竞争，财星木旺而身可任，故富次于名。命师自造，仅按盘面断，不因身份拔高。")
bazi("OC-017","方向：巨富而贵轻。丁火日主酉月、丑辰财库、甲印透时，丝商巨富级家业、富甲南浔；财旺身中和，富足级可足断，官贵则止于捐纳虚衔/地方绅望，晚年家业因后辈与时局渐分化，本人得享富寿终老。","四柱壬戌己酉丁丑甲辰：酉丑辰财势汇聚、甲印护身，富格成立；官星壬水坐戌受制，故贵降格有据。")
bazi("OC-018","方向：报业巨头、晚年横祸。庚金日主子月、寅木财星坐时、辛劫丙杀并见，以报业/言论成巨富大名，地位至报界领袖；晚运火杀攻金、财星被劫之年有刺杀/横死之险，险年在五十余岁、火旺流年（甲午类）前后，难以善终高寿。","四柱己卯丙子庚寅辛巳：庚金寒月、丙巳火杀潜伏待运，寅巳刑动，晚年降格与横祸依据为杀星得地、刑冲引爆。")
bazi("OC-019","方向：才名仕进而险年致命。壬水日主辰月、申金印禄、癸比卯伤，才学与社会声望高，仕至研究院总干事级清贵高位；申卯癸势中藏杀机，行运至火土旺、冲申克水之年（约四十岁前后）有遭暗杀/横祸身亡之险，不得寿终。险年锁定四十岁前后火旺之年。注：两书四柱全异，本例从卡面徐乐吾书本造。","四柱癸巳丙辰壬申癸卯（卡面注明异说不取）：壬得申印、辰库，贵气清；巳火财杀与申合中带破，运至火旺则破局，故断横祸。")
bazi("OC-020","方向：极贵而寿有险关。癸水日主丑月、丑土官星两见、乙食丁财，仕至国民政府主席级/中枢极峰，清望与权位俱全；官重身弱、乙卯泄气，五十岁前后运入火土克水之年有暴疾/中风式险关，寿止于五十余岁，在高位任上去世之象。","四柱己卯丁丑癸丑乙卯：官星叠叠足级极贵；身弱官重为降寿依据，险年定五十岁前后年档。")
bazi("OC-021","方向：军阀首领级贵显、晚年失势。乙木日主酉月、卯禄戌合、丙伤透时、辛杀有制，绿林/行伍出身而登两广主政级高位，食伤制杀成格足级；中年后运离木火之地则杀重压身，兵败下野、晚年寓居终老，富贵不能保全程。","四柱戊午辛酉乙卯丙戌：卯酉冲为格中之瑕、丙火制辛成贵，冲在则后运必有倾覆段，故先贵后衰。")
bazi("OC-022","方向：科名无缘、以命学立身。乙木日主酉月、巳火伤官、丁食戊财、寅根，屡试功名不第为定局——官星金藏巳酉而不透、伤官见官意象，主与科场体制相忤；转而承命学世家之业，以著述卜筮成名立身，一生清贫丰名、晚年桃李著述终老。","四柱辛巳丁酉乙巳戊寅＋安命甲午、大运丙申起（卡面）：伤官旺、官星被伤，科第降格依据在此；食伤生财转业立身为正路。")
# OC meihua / liuren
add("OC-023","方向：钟下所覆为一件圆形/环形金属或玉质器物，且不完好——有缺损/破裂之象。更具体断：为带孔或中空的圆器（如环、镜、钱币类），其一处已残破，完好与否答：不完好。","tradition：meihua（卡面无tradition字段，依据卡面卦象火风鼎变雷风恒自决）\nsystems_used：梅花易数射覆取象；鼎卦象圆器鼎足、中虚可覆藏，变恒主旧物久置；鼎上火下风、器有火炼金属之象，卦中爻动主残缺，故断圆器而破。无更多盘面，置信低、不臆补物主信息。",0.3)
add("OC-024","方向：葬事可成、资费有着落。无资营葬之困将由这位远道来访的青年秀士（即邵雍本人一系的来访者）与易者旧交出资相助而解，棺殓得以办成，不至停柩。应期：来访后数日内筹措、当月内成葬。","tradition：meihua（卡面无tradition字段，依据邵雍梅花易数成例体例自决）\nsystems_used：梅花易数/周易占断互参；遗书预言来访者可托身后事即占题自带锚点，事实优先序下取『来人即资助者』一读，断葬资由访者与旧交凑成。卡面无卦象盘面，残损处已注明并降置信。",0.45)
add("OC-025","方向：应验（positive）。椅底预书之事届期验之成真：到预书所记年月日，椅子果被坐破——由一位体量较重/急坐之客坐塌椅面，应验时间与预书所记日期相合。","tradition：meihua（卡面无tradition字段，依据邵雍预言成例体例自决）\nsystems_used：梅花易数预言验占；占题本身即问预书是否应验，按邵雍成例体例与『预书必验』的占题锚点断其应验，应验对象为邵家之椅、承受对象为坐椅之客，对象已对齐。卡面无具体日期数字，不臆补。",0.5)
def liuren(cid,pred,basis,conf=0.55):
    add(cid,pred,"tradition：liuren（卡面无tradition字段，依据卡面课式三传自决）\nsystems_used：大六壬（课格、三传天将链、空亡）；"+basis,conf)
liuren("OC-026","方向：功名可望而迟得、且二人不同程。初传乙未青龙主喜庆文书发动，中传己亥螣蛇主虚惊反复、亥为巳月空亡旬内（甲午旬辰巳空，亥不空，然螣蛇乘之主多梦多疑），终传癸卯玄武主暗中名次/次等功名。断：今年功名有一人得中/得荐而名次偏后或副榜，另一人只得虚声、下科再发；应期在秋冬之交（未亥月令之后、卯木得水生之时），以月档计。","课式涉害曲直：曲直木格主文事功名，三传未亥卯三合木局成势，故方向不作落空断；玄武终传压等级，故不拔高为高第。盘面只有课式三传月将空亡，天盘四课全图未给，守残损边界不臆补。")
liuren("OC-027","方向：此行不得意（negative）。课名无禄无路已示官禄无门、行路无通；三传癸酉六合、戊辰太阴、亥青龙而亥落甲子旬空亡，终传空亡主终无着落。断：北上诏行或中途受阻、或到京不得召用而返；身体有劳顿小疾无大碍，老母在家安稳无恙——不安者在己身行程，不在母。应期：此行一程之内（月档），终以南返收束。","三传由合到阴到空、逐传走弱，青龙乘空为虚喜，事实核对：时北方兵事正紧与『无路』课名同向，故断不得意。盘面残损守界：无四课全列，只据课式三传空亡作断。")
liuren("OC-028","方向：得官而位中平。初传辛卯玄武主暗中关节/名次靠后，中传丙戌朱雀主诏敕文书临身，终传癸巳白虎主实授带兵刑/武职气或驿传之任。断：入觐考选后得授一实职，品级为中下层京职或外任佐贰偏上（如主事/知县级），非清要高擢；文书先到、实授稍迟，应期在次年春夏间（月/年档，先定年再定月）。","课式重审斫轮主反复甄别后成器，朱雀中传为得官锚点；玄武白虎压等级，故不拔高。盘面只有课式三传月将空亡，守界不臆补四课。")
liuren("OC-029","方向：诸事中平、子事胜于己事。初传乙未白虎主道路劳顿与母寿之忧发动，中传癸卯六合主人事和合、贵人接引，终传己亥天后主母氏/阴人得安。断：携子求官，子可得一小职或得贵人许诺而事成过半，占者本人所求只得虚声；家中近九十之母寿安无大碍、可赶上为其祝寿，来回路程辛苦而无大险。应期：亥月前后事定（月档）。","三传未卯亥三合木局再成、人事和合为据；白虎初传只主劳顿与忧心，天后终传护母，故不作母凶断——应验对象逐名对回：母安、子成其半、己虚声。盘面残损守界同前。")
liuren("OC-030","方向：两问分断——淮扬巡按差不可复（negative），吏书缺可照旧（positive）。初传癸巳太常主旧制典章，中传丙戌六合主文书和合存续，终传辛卯太阴主暗中保留。断：巡按差废而不复、复设之议无下文；吏书之缺则照旧保留、人得留任或按旧例补上。应期：当年内两事各定（月档）。","课式重审铸印：铸印主印信职缺之存立，六合太阴护『缺』而不护『复差』，故两问一否一可，不许混作一断。盘面只有课式三传月将，守界作断。")
# WP
def wp(cid,pred,basis,conf=0.6,trad="western-astrology"):
    add(cid,pred,f"tradition：{trad}（卡面无tradition字段，依据卡面行星配置/问事体例自决）\nsystems_used："+basis,conf)
wp("WP-001","Direction: Yes — a major collective affliction, specifically a global epidemic/pandemic disease outbreak centred on 2020-2021. The Jupiter-Saturn-Pluto conjunction in Capricorn at the cyclical-index low indicates mass illness, high mortality among the elderly, lockdown-style restriction and economic shutdown beginning early 2020 and running through 2021. Severity: the gravest collective health crisis in a century, comparable to 1918.","西洋占星周期学（outer-planet cluster + cyclical index）；土冥合主瘟疫与大规模死亡、木星放大、摩羯主国家机器封锁，历史同构 1918 即流感大流行，故落到事件级：呼吸系统大流行病。卡面配置完整。",0.72)
wp("WP-002","Direction: Barack Obama wins. Obama first clinches the Democratic nomination, then defeats John McCain in the 4 November 2008 general election. The Saturn-Uranus opposition exact on Election Day marks the fall of the old order/incumbent party and the election of the insurgent, change-bearing candidate. Margin: a clear, not razor-thin, victory.","西洋占星选举占星：土天对冲为政权更替与反建制签名，现任执政党候选人麦凯恩承土星旧秩序之压，奥巴马承天王星变革之象，故断变天。",0.65)
wp("WP-003","Direction: Barack Obama is re-elected. Incumbent Obama defeats Mitt Romney on 6 November 2012 despite the Mercury-retrograde Election Day causing counting delays, disputes and confusion in the process. Result: Obama wins both the Electoral College and the popular vote; the retrograde shows in the mechanics, not in overturning the outcome.","西洋占星选举占星：现任者盘面优势未被挑战者压过；水逆当日只主流程混乱与迟滞，按事实优先序不许以水逆翻转终局。",0.62)
wp("WP-004","Direction: Donald Trump wins (upset). Against the polling consensus favouring Hillary Clinton, the conference-panel weight of chart evidence points to Trump: Clinton's chart carries the heavier affliction into 8 November 2016, and Trump takes the Electoral College while likely losing the popular vote. Decider: late-campaign damage to Clinton's standing.","西洋占星选举占星 panel 体例：以候选人本命与选举日行运对决、民调只作背景事实不作锚点；断冷门胜出并注明票数结构（选举人票胜、普选票负）。",0.55)
wp("WP-005","Direction: Donald Trump wins. The astrologer who alone picked Trump as Republican nominee out of 17 contenders follows the same chart logic to its conclusion: Trump defeats Hillary Clinton on 8 November 2016 via the Electoral College, in the cycle's biggest forecasting upset.","西洋占星选举占星：同一算者前后两断同源（提名断已验其法），延续其取舍断 Trump 终胜；与 WP-004 独立同向，属多路收敛。",0.55)
wp("WP-006","Direction: Britain votes Leave. The 23 June 2016 referendum returns a Leave majority, narrowly (roughly 52-48), despite February polls showing Stay ahead — the large undecided bloc breaks disproportionately for Leave under the Uranus-Ceres conjunction in Aries on referendum day, a signature of abrupt national self-assertion and rupture with the existing order.","西洋占星 mundane astrology：英国 1066/1801/1922 国家盘与公投日天王星突发性合相主决裂，未决选民为关键变量，故断窄幅脱欧。",0.58)
add("WP-007","Direction: Donald Trump wins, and what decides it is Hillary Clinton herself — her email controversy and Clinton Foundation entanglements destroying trust at the decisive moment. The cards point to a hidden/buried liability around the woman candidate surfacing late, a male outsider taking the prize on 8 November 2016, and Clinton winning the popular vote but losing where it counts.","tradition：tarot（卡面无tradition字段，依据卡面『tarot reader draws cards』自决）\nsystems_used：塔罗（Waite 牌义体例）＋时事事实核对；占题自带锚点即已公开的电邮与基金会争议，按事实优先序落为『决定因素』，断语落到人物与事件级。卡面未给具体牌面，残损处注明、置信相应下调。",0.52)
wp("WP-008","Direction: Narendra Modi and the BJP/NDA win, with a renewed and larger mandate. The BJP retains power and increases its own majority in the Lok Sabha (crossing 300 seats on its own), Rahul Gandhi's Congress improves slightly but remains a distant second. Result declared 23 May 2019.","吠陀/印度占星选举断：现任者 Modi 之盘势强于挑战者、执政联盟星势成局，故断连任且席位扩大，落到席位量级。",0.66,"vedic-astrology")
wp("WP-009","Direction: No — India will not win the 2019 Cricket World Cup. India perform strongly and reach the semi-finals as favourites, but fall in the knockout stage (semi-final) to an underdog opponent in a rain-affected match; the trophy goes to the host, England. Kohli's chart shows tournament glory falling just short at the final hurdles.","吠陀占星赛事断：印度队长盘面强势只支持深轮次不支持登顶，强而差一步为降格依据，故断止步四强。卡面未给完整盘面，置信中。",0.55,"vedic-astrology")
wp("WP-010","Direction: Joe Biden wins. Despite the three Vedic astrologers disagreeing among themselves, the balance of chart evidence — Biden's Scorpio-Ascendant chart receiving the stronger dasha/transit support into 3 November 2020 — gives Biden the presidency, narrowly in the decisive states, after a delayed count.","吠陀占星：三家分歧并列呈现后由算者自决，取 Biden 盘面行运较强一路；Trump 之木星相位只主声势不主终胜。",0.55,"vedic-astrology")
wp("WP-011","Direction: Donald Trump is re-elected (this reading's call). On the chart evidence given — Jupiter in Trump's second house aspecting the tenth-house Sun — the incumbent's authority signature is judged too strong to dislodge: Trump defeats Biden on 3 November 2020, defying the polls, with his COVID recovery read as a surge of personal vitality into election day.","吠陀占星：严格按卡面所给单一盘面锚点（木星居二宫照十宫太阳）作断，此为该受访算者一路之断；卡面只给 Trump 一方盘面、无 Biden 对照，残损已注明，故只报此一路终局、不混入他家结论。",0.5,"vedic-astrology")
wp("WP-012","Direction: Biden wins the election and does take the presidency — but only after a contested aftermath. Trump refuses to concede, alleges fraud over mail-in voting, and pursues legal challenges; the transfer is delayed and turbulent, with civil unrest, yet Biden is inaugurated in January 2021 and Trump leaves office. Two-stage: near stage disputed count and litigation (Nov-Dec 2020), far stage confirmed transfer (Jan 2021).","西洋占星 mundane：选举日与就职日行运分段读，近段主争议、远段主秩序落定，远段触发为就职日太阳行运成局，故两段俱报而终局单判 Biden 就任。",0.63)
wp("WP-013","Direction: Labour wins in a landslide. Keir Starmer's Labour defeats Rishi Sunak's Conservatives on 4 July 2024 by a very large margin — Labour takes a commanding Commons majority (400+ seats) and the Conservatives fall to their worst result in modern history (around or below 130 seats). Sunak's D-Day early departure is read as the campaign's symbolic self-inflicted wound.","西洋占星 mundane＋民调事实核对：二十点民调差距为占题事实锚点，盘面（巨蟹月选举、现任者受蚀压）同向，故足级断压倒性胜出并落到席位量级。",0.7)
# YM liuyao
def ly(cid,pred,basis,conf,reason):
    add(cid,pred,"tradition：liuyao（卡面tradition字段）\nsystems_used：六爻纳甲；"+basis,conf,LT(reason))
ly("YM-002","终局：兄弟病可愈、不致命（positive，单一终局）。近段病势缠绵有反复，远段转愈。应期双层：窗口为出空填实与子孙得值之旬内至下月，窗口内主坐标取子孙辰/未土得值之日（辰日为主坐标）。两段：近段官鬼亥水持世、病势在身未退；远段父母卯木动化子孙辰土、药效与生机续上，子孙两现护兄，故终局向愈。","用神兄弟午火：午火居四爻得月日生扶不弱；忌神官鬼亥水持世主病缠，然五爻妻财申金动化子孙未土、初爻父母卯木动化子孙辰土，子孙福神两动制鬼护兄。动化方向：财化子孙、父化子孙皆向生机；反转条件：子孙若空破则翻凶，本盘子孙未空未破，反转不成立。应期三路：冲实（辰冲戌子孙）有候选、填实（子孙值日）有候选、逢值（午火值日）主病值非愈值舍之；取填实/冲实合流之辰日。门类应期对表：病占首选子孙值日/原神得生，在候选内取中。应验对象复述：病者为占者之兄弟，主断语承受与应验同为兄弟本人。应期尺度：病占日档，依据为近病问势、盘面动爻密集支持日级。",0.62,"两动爻皆化子孙护用神，主断依本卦动化直取可愈，未改主断、未用备选判法、判读无争议，三项皆false。")
ly("YM-003","终局：占官不成/迁转落空（negative，单一终局）。世爻子孙子水动化官鬼巳火看似官来就身，然子水在戌月戌日休囚受克、化出巳火又被子水回克之势未成，且三爻妻财卯木动化兄弟申金、财化兄主耗费阻隔。应期双层：窗口为本旬至下月任命期，窗口内主坐标取官鬼巳火值日（巳日）为落空见分晓之点——至巳日无实授消息即定落空。","用神官鬼：官鬼巳火居二爻应位静而受日月之克生参半、不得世应生合；世动化官为虚动——世爻子孙本为克官之福神，化官属化出虚象。动化方向：世化官方向主『求而不得实』，财化兄主破费；反转条件：官鬼得月建生旺且世爻有气才翻成，本盘皆不成立。应期三路：逢值（巳日）有候选、冲实无（官不空不伏）、填实无，取逢值定分晓点。门类应期对表：仕途首选官鬼值日，在候选内取中。应期尺度：月档内日点，问仕途迁转以月为窗口、日为分晓坐标。",0.58,"世爻动化官鬼一象有『官来就身』与『虚动』二读，本席按旺衰裁定虚动并在basis留痕，主断未中途更改、未用备选，三项皆false（分歧已在内部裁决、非悬而未决之disputed）。")
ly("YM-004","终局：子病凶危、难愈（negative，单一终局）。世爻兄弟酉金四爻独动化父母戌土，属占子病中『独发』——用神子孙不现于动、子孙卯木妻财位静伏受酉金动爻冲克（卯酉冲），子星被冲又不得生。近段病势急重，远段无子孙动来救应，终局向凶：病在数日至旬内见危重关口。应期双层：窗口为占后一旬，窗口内主坐标取卯木子孙被冲之酉日/卯日冲实点，取酉日为主坐标（金动冲子最急之日）。应验对象复述：病者为占者之子，主断语承受与应验同为其子本人。","用神子孙：子孙即妻财卯木居三爻（子病占以子孙为用），卯木在申日受克、又被世爻酉金动冲，互卦再成剥象（变卦山地剥主剥落）。动化方向：兄动化父主耗费医药而子星受冲；反转条件：子孙得日月生扶或动而化生才翻愈，本盘子孙静而受冲，反转不成立。应期三路：冲实（酉冲卯）有候选且最急、填实（卯日）次之、逢值（子孙值日同卯）与填实同点，取冲实酉日为主坐标，余路舍弃理由为尺度同而冲力更急。门类应期对表：病占危重首选冲用神之日，在候选内取中。应期尺度：日档，近病急症、独发冲子支持日级定位。",0.6,"独发一爻定主断，按独发章直断，未改主断、未用备选、判读无争议，三项皆false。")
ly("YM-005","终局：占官可成而位卑迟得（positive，单一终局）。世爻妻财寅木初爻独动化官鬼巳火——财动生官、官来就世，六合变六冲主先合后散、先许后变：官职终得，然所得为小职/暂代，进身后不久有调动。应期双层：窗口为占后一至两月，窗口内主坐标取官鬼巳火值日所属之巳月节点（以月为窗口尺度、巳月为主坐标月）。","用神官鬼午火居四爻得寅木世爻动生、又世化巳火官星，官与世两重相连。动化方向：财化官主由财路/人事运作得官；反转条件：世爻化官遭回头克才翻空，巳火得寅生不回克，反转不成立。应期三路：逢值（巳月）有候选、填实（官不空）无、冲实（冲合之冲）主散不主成舍之，取逢值。门类应期对表：仕途首选官鬼值期，在候选内取中；六合变六冲压等级，故断小职迟得不拔高。应期尺度：月档，仕途迁转问事本以月计。",0.6,"独发财化官直取主断，未改主断、未用备选、判读无争议，三项皆false。")
ly("YM-007","终局：子尚存、不作夭亡断（positive，单一终局，存亡问以『存』落定）。然归耗未至、人在外受困滞：四爻父母未土世爻动化子孙亥水，子星化出于世爻——子息消息将由家中/文书牵出，上爻妻财卯木动化父母未土主音信转迟。应期双层：窗口为占后一月内得确切消息，窗口内主坐标取子孙亥水值日（亥日）为消息到家之点；人归则更迟于消息，不在本问终局内。应验对象复述：所占为出门之子，主断语承受与应验同为其子本人（存）、消息应于占者之家。","用神子孙：子孙亥水不现本卦、伏藏待出（飞伏章理：子孙化出于世爻父母，属有根可出，非绝象）；父母两现主音信文书。动化方向：父化子主由长辈/家书得子讯、财化父主讯迟；反转条件：子孙化空化绝才翻亡，本盘亥水在子日得旺、未土世爻不克绝，反转不成立。应期三路：逢值（亥日）有候选、冲实（巳冲亥动伏）为备选舍之（主消息骤至而非定点）、填实（子不空）无，取逢值。门类应期对表：存亡/消息类首选伏神值日，在候选内取中。应期尺度：日档内取点、月档为窗口，近事消息问以此尺度。",0.55,"用神子孙伏藏化出，依飞伏与干化之理直断为存，未改主断、未用备选；存亡重问置信已下调，判读内部无未决争议，三项皆false。")
ly("YM-008","终局：考秩得中上等第、考核过关（positive，单一终局）。静卦泽地萃：官鬼巳火持世居二爻、得亥月冲巳为月破之瑕，然兄弟酉金应爻旺、父母两现主文书档案齐备，世应无冲克、卦名萃主聚而见品评。断等第为中上（二等/优等下限），不至头名亦不落末等。应期：考期当月内揭晓（月档，以月为单位不定日）。","用神官鬼/父母并重（考秩以官为主、父母文书为辅）：官鬼巳火持世与占者相连、父母未土两现主考卷档案有着落；静卦无动则事按现局落定。动化方向：无动爻，记『无动化』；反转条件：世爻月破若再逢日冲则翻末等，本盘日辰寅木生巳火补破，反转不成立。应期三路（静卦）：逢值（考月）取之、冲实填实皆无候选（无空无伏），已逐路注明。门类应期对表：考核类对表无专条者按三步原序——本例以月档落定。应期尺度：月档，考核揭晓以月计。",0.57,"静卦按现局直断，未改主断、未用备选、判读无争议，三项皆false。")
ly("YM-009","终局：摇会可得（positive，单一终局）。静卦地水师：妻财午火持世居四爻、得辰月生扶、甲寅日木生火，财星旺而持世主财到手；子孙寅木初爻与日辰同气暗助，官鬼两现主会中规矩人干预而无破财之兄动。断本会可中/可得会银，得数足额而非折减。应期：会期即本轮（旬内），主坐标取妻财午火值日（午日）为得会之点。","用神妻财午火持世旺相为得财正象；静卦无兄动劫财。动化方向：无动爻记『无动化』；反转条件：财遭日月冲克才翻失，本盘日辰寅木生财、月建辰土泄而有生，反转不成立。应期三路：逢值（午日）取之、冲实（财不空）无、填实无，逐路已注。门类应期对表：求财/摇会首选财星值日，在候选内取中。应期尺度：日档，摇会为近事、以轮次旬内计。",0.63,"静卦财持世直断可得，未改主断、未用备选、判读无争议，三项皆false。")
ly("YM-010","终局：临产将产、母子可安（positive，单一终局）。五爻兄弟申金独动化父母未土，子孙亥水居三爻得酉金应位之生、临产问以子孙为用，子星不空不破、动爻化父母主母体发动。断当日/次日即产（应期日档），产程稍迟而终顺，子以亥/子水时辰落地之象较强。应期双层：窗口为占后两日，窗口内主坐标取子孙亥水值日逢时之亥时段（以日为窗口、亥日亥时为主坐标点）。应验对象复述：产者为临产妇人、所产为其子，主断语两对象分别对回：母安、子顺。","用神子孙亥水：午月己巳日，亥水休囚为瑕，然得兄弟酉金、动爻申金金局生水补力，时辰章以时取应。动化方向：兄动化父主母体与产程发动；反转条件：子孙空破或鬼动克子才翻危，本盘官鬼午火应位静而不克亥（午亥暗合），反转不成立。应期三路：逢值（亥日/亥时）取之、冲实（巳冲亥，日辰巳正冲子孙——冲动即产发动，作发动信号并入逢值路）、填实（子不空）无，取舍已注。门类应期对表：临产首选冲子孙之日时与子孙值时，在候选内取中。应期尺度：日档，临产以时日计、盘面支持日级。",0.6,"独发兄化父直断将产，未改主断、未用备选、判读无争议，三项皆false。")
ly("YM-012","终局：子将归、可归（positive，单一终局）。初爻妻财子水独动化兄弟丑土——行人占以子孙酉金为用，子孙持世居五爻旺相（酉月子日金水相生），世即子星临身主归意已动、人已在归途。独动之财化兄主路上有耗费迟滞一程。应期双层：窗口为占后数日至一旬，窗口内主坐标取子孙酉金值日（酉日）为到家之日。应验对象复述：归者为占者之子，主断语承受与应验同为其子本人。","用神子孙酉金持世旺相为归正象；独发在初爻主动在足下/行程之始。动化方向：财化兄主途中耗费、只调量级不翻方向；反转条件：子孙空破或化绝才翻不归，本盘子孙临月建酉、旺极，反转不成立。应期三路：逢值（酉日）取之、冲实（子孙不空，卯冲酉为冲动归期备选——与逢值同属酉点附近，舍冲实因冲主到门骤至、定点仍以值日为准）、填实无，取舍已注。门类应期对表：行人归期首选用神值日，在候选内取中。应期尺度：日档，归期近事、独发支持日级。",0.66,"独发定行程、子孙持世旺相直断归，未改主断、未用备选、判读无争议，三项皆false。")
ly("YM-013","终局：妻病可愈而慢愈（positive，单一终局）。五爻妻财子水应爻独动化父母巳火——用神妻财即病者，子水在午月己巳日休囚受克为病重之象，然独动化父母（医药/长辈照护）且初爻妻财子水静守有根、官鬼寅木两现持世生扶之势在。近段病势沉重，远段经医药调治渐退。应期双层：窗口为占后一月，窗口内主坐标取妻财子水得值之子日/亥日逢生点，取亥日为主坐标（亥水得生而非子水值日逢冲）。应验对象复述：病者为占者之妻，主断语承受与应验同为其妻本人。","用神妻财子水：独发章独动之爻即用神发动，化父母主靠医药转圜；原神官鬼木持世两现（木生火病位而言鬼为病、于妻病占官鬼为病星，寅木不得月令、巳日合绊）病星不旺为可愈据。动化方向：财化父向医药生机；反转条件：用神化空化墓或鬼旺克财才翻凶，本盘化巳火为日辰同气非空，反转不成立。应期三路：逢值（亥日子水得生值日）取亥、冲实（子不空）无、填实无，取舍已注。门类应期对表：病占首选原神/用神得生之日，在候选内取中。应期尺度：日点月窗，近病问以此尺度。",0.56,"独发即用神发动，按独发章直断慢愈，未改主断、未用备选、判读无争议，三项皆false。")
ly("YM-014","终局：家宅有火灾之虞而可防免/火起不大（positive向『可免大祸』落定，单一终局）。四爻官鬼午火独动即火星发动——未月戊午日火势得令得日，火险真实存在于占后近日；然午火动化父母未土，火泄于土、动而化宅（父母为家宅），主火头被宅体/人为处置承接，子孙子水初爻制火之神在位。断：近日（数日内）有一次小火情/火险惊扰（如灶火、电火、祭祀火），及时扑灭，不成燎原大火，家宅保全。应期双层：窗口为占后五日，窗口内主坐标取官鬼午火再值之午日为主坐标。应验对象复述：应验对象为占者之家宅本身（非人对象），火情落于宅内灶/电位，不回收到家人伤亡上。","用神父母（家宅）＋忌象官鬼火：鬼动示险、化父示险归于宅而被承接，子孙制鬼在位为可免据。动化方向：鬼化父主火势泄缓；反转条件：火动化进神或子孙空破才翻大火，本盘化退泄、子孙不空，反转不成立。应期三路：逢值（午日）取之、冲实（火不空）无、填实无。门类应期对表：宅火险近事首选忌神值日，在候选内取中。应期尺度：日档，火险为即时近事。",0.58,"独发鬼动示险、化父定可承接，主断一次落定，未改主断、未用备选、判读无争议，三项皆false。")
ly("YM-015","终局：功名可成而不在即年、迟至再下一科（positive，单一终局）。四爻父母戌土独动化兄弟酉金——父母为功名文书用神，戌土在巳月甲戌日得旺、独动主文书发动；然化兄弟酉金为退耗之象，且世爻子孙子水（福神克官）居五爻，官鬼巳火应爻静而得月建。断：本科（壬午年乡试）名落或副榜边缘，下科（乙酉年前后一科）正式中举。应期双层：窗口以年为尺度——先定年：下科之年（年档），窗口内主坐标取该科放榜之秋月（月），不径落日。","用神父母/官鬼并参：父动示功名事动、官静待运。动化方向：父化兄主本科耗而落、待兄退之科成；反转条件：父动化进或官动生世才翻即年成，本盘化兄为退，反转不成立、故迟断有据。应期三路（年档）：逢值（下科酉年与化出酉金同气）取之、冲实（父不空）无、填实无，取舍已注。门类应期对表：功名首选科年逢值，在候选内取中。应期尺度：年档，乡举三年一科、问『乡举之期』本以年计，合通则(k)年档先年后月。",0.57,"独发父化兄定迟科，主断一次落定，未改主断、未用备选、判读无争议，三项皆false。")
ly("YM-017","终局：访友可遇而迟遇（positive，单一终局）。五动一静之局，独静者为五爻兄弟申金应爻——独静章以静爻为枢：朋友一方（应爻）静守不移、占者多动奔走，终在应爻所指之地/之日遇合。世爻官鬼午火动化妻财卯木主行程有耗、初爻父母辰土动化官鬼巳火主先有文书消息。应期双层：窗口为占后一旬内，窗口内主坐标取独静之申金值日（申日）为遇友之日。应验对象复述：所访为占者之友，遇合应于友本人（应爻），非他人代见。","用神取应爻/兄弟（访友以应与兄为友象）：应爻申金独静为枢、余爻皆动主占者奔波。动化方向：多爻动化纷纷主行程波折只调量级；反转条件：独静之爻空破才翻不遇，本盘申金在未月丙午日不空不破、得辰戌土动生，反转不成立。应期三路：逢值（申日）取之、冲实（申不空，寅冲申为备选舍之——冲静为骤遇、定点以值日为正）、填实无，取舍已注。门类应期对表：访人/遇合首选独静爻值日，在候选内取中。应期尺度：日档，何日遇友本以日问。",0.6,"五动一静按独静章以静爻为枢直断，主断一次落定，未改主断、未用备选、判读无争议，三项皆false。")
ly("YM-018","终局：子将归、可归（positive，单一终局）。五动一静，独静者为四爻子孙酉金持世——子星即独静之枢、静而临世主子安稳在外有定所、归期系于此静爻得动之时。群动之爻：父母两动主消息频传、兄弟两动主途中耗费、官鬼卯木动化父母午火主行程文书催归。应期双层：窗口为占后一旬至半月，窗口内主坐标取独静子孙酉金被冲动之卯日为到家之日（静爻逢冲则动、冲日即归日，卯木又为动爻官鬼之气）。应验对象复述：归者为占者之子，主断语承受与应验同为其子本人。","用神子孙酉金独静持世：巳月乙丑日，酉金得丑土生、月建巳火合酉（巳酉半合）主归意被行程合住而迟，逢冲开合则归。动化方向：群动化子孙者两处（兄化子）主归途终向子星收束；反转条件：独静子孙空破才翻不归，本盘酉金不空不破，反转不成立。应期三路：冲实（卯冲酉开合）取之、逢值（酉日）为备选舍之（酉日只逢值不冲开巳酉之合、归势未发）、填实（子不空）无，取舍已注。门类应期对表：行人归期首选冲开合住用神之日，在候选内取中。应期尺度：日档，归期近事以日计。",0.62,"五动一静按独静章以静爻子孙为枢、逢冲定归，主断一次落定，未改主断、未用备选、判读无争议，三项皆false。")

